    sticks.sort(reverse=True)
    n = len(sticks)

    # Try all combinations of 3 sticks from largest to smallest
    best_triangle = None
    best_perimeter = 0

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a, b, c = sticks[i], sticks[j], sticks[k]

                # Check if they can form a triangle
                if can_form_triangle(a, b, c):
                    perimeter = a + b + c

                    # Update best triangle if this has a larger perimeter
                    if perimeter > best_perimeter:
                        best_perimeter = perimeter
                        best_triangle = [a, b, c]
                    elif perimeter == best_perimeter:
                        # If same perimeter, prefer larger largest side
                        if a > best_triangle[0] or (a == best_triangle[0] and b > best_triangle[1] or (a == best_triangle[0] and b == best_triangle[1] and c > best_triangle[2])):
                            best_triangle = [a, b, c]

    if best_triangle is None:
        return [-1]

    # Return in increasing order
    return sorted(best_triangle)

